/**
 * A USA EQUIVALENT NEEDS A DATED EXCHANGE RATE (operator 2026-09-12: "ensure all can be local currency and also be shown
 * in USA equivalent"). The dataset carries no exchange-rate column and the paper publishes none, so a conversion factor
 * must arrive as a dated, sourced row in docs/asks/2026-09-12_fx_to_usd.psv — REGENERATED here, never typed. Until a
 * currency has a row, its USD line says what is missing instead of showing a number nobody can trace.
 */
export interface FxRow { currency: string; perUsd: number; asOf: string; source: string }
export const FX_TO_USD: FxRow[] = [
  { currency: "USD", perUsd: 1, asOf: "2026-09-12", source: "identity — the same currency; no conversion" },
]


/**
 * The key of a ROW. The operator's rows keep `lang:cc` (elections and ledgers already hold those ids); an APPROVED row
 * that would collide with one of his — the federal floor beside Austin, a fill beside his NULL — carries its name too, so
 * no row can ever overwrite another in the index.
 */
const slug = (s: string): string => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
export const regionId = (r: Pick<RegionRate, "lang" | "cc"> & { name?: string; approved?: string }): string =>
  r.approved ? `${r.lang}:${r.cc}:${slug(r.name ?? "")}` : `${r.lang}:${r.cc}`;

/**
 * O(1) row lookup. This was `REGION_RATES.find(r => regionId(r) === id)` — a 114-row scan building a string per row,
 * on every render, and now called once per pod member. Built once at module load instead.
 */
const REGION_INDEX: ReadonlyMap<string, RegionRate> = (() => {
  const m = new Map<string, RegionRate>();
  for (const r of REGION_RATES) if (!m.has(regionId(r))) m.set(regionId(r), r);   // first wins; the operator's rows come first
  return m;
})();
export const findRegion = (id: string): RegionRate | undefined => REGION_INDEX.get(id);

/**
 * unit.settle's settlement ladder, derived from each row's own two flags. Counting the table this way reproduces the
 * paper's published partition exactly — 29 / 37 / 35 / 13 — which is how the transcription was verified.
 */
export type SettleTier = "published" | "pending" | "no_single_rate" | "no_official_rate";
export function tierOf(r: RegionRate): SettleTier {
  if (r.rate !== null) return "published";
  if (!r.published) return "no_official_rate";
  return r.noSingleRate ? "no_single_rate" : "pending";
}

/** What to tell a person whose region cannot settle yet — never a figure, never zero, always what is missing. */
export const TIER_REASON: Record<SettleTier, string> = {
  published: "",
  pending: "A national rate exists but is not yet loaded here. Recoverable by data entry, not by policy.",
  no_single_rate: "Rates here are sectoral, regional or collectively bargained. A published selection rule is required.",
  no_official_rate: "No statutory minimum exists at any level. Settles under the Global Agreed Standard.",
};

/**
 * JURISDICTIONS — every PLACE a person can elect, one entry each, whatever number of source rows describe it.
 *
 * OPERATOR RULING, 2026-09-11 (docs/asks/2026-09-11_election_of_locality.md): "ensure optimized and includes
 * election of locality and regional min wage." A person elects a place, never a language — Switzerland used to appear
 * three times, once per language, with the same rate each time.
 *
 * OPERATOR RULING, 2026-09-12 (docs/asks/2026-09-12_traceable_dataset_gps_usd_equivalent.md): "use this traceable
 * data set". THE DATASET IS THE PRIMARY SOURCE OF FLOORS. It creates the places first; his 2026-09-10 rows and the rows he
 * approved on 2026-09-11 then attach to the place they describe as HISTORY:
 *   · where the dataset publishes a floor, the dataset's figure settles and the history figure is recorded beside it;
 *   · where the dataset names the place but publishes no floor ("candidate", "verification pending"), NOTHING settles —
 *     the dataset demoted that figure on purpose (his own Nigeria row is its candidate); the history figure stays in
 *     view, labelled, and the dataset's status is what the person reads;
 *   · a place the dataset does not name at all — Austin, Beijing, Geneva, a Canadian province — settles from its history
 *     row under that source, exactly as before. No figure is ever guessed.
 * No source row is edited to agree with another; the gate reconciles every row of every source to a place.
 */
export type PlaceSource = "dataset-2026-09-12" | "operator-2026-09-10" | "approved-2026-09-11" | "hi_rates.py";
export interface Jurisdiction {
  id: string;              // what a member elects — stable; every history row's regionId also resolves to this place
  cc: string;              // ISO 3166-1 alpha-2 (US territories are localities of "US")
  name: string;            // the full name, e.g. "United States — New York · Remainder of state"
  country: string;         // the part before the em dash
  locality: string | null; // the part after it — null for the country itself
  currency: string;        // "" only where no source names one
  rate: number | null;     // THE SETTLING RATE — the dataset floor, else a history figure, else null
  tier: SettleTier;
  note: string;
  langs: string[];         // every language any source publishes this place under
  source: PlaceSource;     // where the settling rate comes from (the dataset's own tier where nothing settles)
  /** hi_rates.py's USD figure for the same country or state, where it holds one. Shown beside, never converted into. */
  usdMirror: number | null;
  /** True when one of the operator's own 2026-09-10 rows describes this place. */
  fromOperator: boolean;
  /** The dataset row(s) behind this place — provenance a person can follow to the statute. */
  dataset?: DatasetRow;
  /** History figures that differ from what settles, or that fill where the dataset is silent — stated, never merged. */
  history: string[];
}

/** "Canada — Québec" → ["Canada", "Québec"]. The em dash is the paper's own separator. */
const splitName = (name: string): [string, string | null] => {
  const i = name.indexOf(" — ");
  return i < 0 ? [name, null] : [name.slice(0, i), name.slice(i + 3)];
};

/** The dataset lists the US territories as countries; the record elects them as localities of the United States. */
const US_TERRITORY: Record<string, string> = { PR: "Puerto Rico", GU: "Guam", VI: "U.S. Virgin Islands", MP: "Northern Mariana Islands", AS: "American Samoa" };

const datasetTier = (d: DatasetRow): SettleTier =>
  d.floor !== null ? "published" : d.published === false ? "no_official_rate" : d.noSingleRate ? "no_single_rate" : "pending";

/** History rows' regionIds → the place they attach to, so an election recorded under an old id still resolves. */
const ALIAS = new Map<string, Jurisdiction>();

export const JURISDICTIONS: Jurisdiction[] = (() => {
  const byKey = new Map<string, Jurisdiction>();            // "cc|name" → place
  const byCountry = new Map<string, Jurisdiction>();        // cc → the country-level place
  const subCount = new Map<string, number>();
  for (const d of DATASET_ROWS) if (d.sub) subCount.set(d.sub, (subCount.get(d.sub) ?? 0) + 1);

  // 1 · the dataset creates the places
  for (const d of DATASET_ROWS) {
    let cc = d.cc, country = d.name, locality: string | null = null, id = `ds:${d.cc}`;
    if (d.type !== "Country") {
      country = "United States";
      locality = (subCount.get(d.sub) ?? 1) > 1 ? `${d.name} · ${d.scope}` : d.name;
      // "< $405,000" and ">= $405,000" must not slug to the same id — the comparison is part of the scope's identity
      id = (subCount.get(d.sub) ?? 1) > 1 ? `ds:${d.sub}:${slug(d.scope.replace(/<=/g, " le ").replace(/>=/g, " ge ").replace(/</g, " lt ").replace(/>/g, " gt "))}` : `ds:${d.sub}`;
    } else if (US_TERRITORY[d.cc]) {
      cc = "US"; country = "United States"; locality = US_TERRITORY[d.cc];
    }
    const name = locality ? `${country} — ${locality}` : country;
    const j: Jurisdiction = {
      id, cc, name, country, locality, currency: d.currency ?? "", rate: d.floor, tier: datasetTier(d),
      note: d.floor !== null && d.hourly !== null && d.hourly !== d.floor
        ? `${d.note} Published ${d.hourly} ${d.currency}/h; the effective floor ${d.floor} settles.`
        : d.candidate !== null ? `${d.note} Candidate ${d.candidate} ${d.currency}/h from a secondary source — shown, never settled.` : d.note,
      langs: [...d.langs], source: "dataset-2026-09-12",
      usdMirror: d.type !== "Country" ? (US_STATE_RATES[d.name] ?? null) : (COUNTRY_RATES[d.name] ?? null),
      fromOperator: false, dataset: d, history: [],
    };
    byKey.set(`${cc}|${name}`, j);
    if (locality === null) byCountry.set(cc, j);
  }

  // 2 · the operator's rows and the approved rows attach as history, or create the places the dataset does not name
  for (const r of REGION_RATES) {
    const [country, locality] = splitName(r.name);
    const src: PlaceSource = r.approved ? "approved-2026-09-11" : "operator-2026-09-10";
    // a national row, or a "Federal …" row, describes the dataset's country-level place
    const target = (locality === null || /^Federal\b/.test(locality)) ? byCountry.get(r.cc) : byKey.get(`${r.cc}|${r.name}`);
    if (target) {
      for (const l of [r.lang]) if (!target.langs.includes(l)) target.langs.push(l);
      if (!r.approved) target.fromOperator = true;
      const label = `${r.approved ? "approved 2026-09-11" : "operator 2026-09-10"}${locality ? ` (${locality})` : ""}`;
      // THE DATASET GOVERNS EVERY PLACE IT NAMES. A history figure never settles a dataset place — where the dataset says
      // "candidate" or "verification pending" it has demoted that figure on purpose (his own Nigeria row is the dataset's
      // candidate). The figure is kept in view as history; the dataset's own status is what the person reads.
      if (r.rate !== null && (r.rate !== target.rate || r.currency !== target.currency)) {
        target.history.push(target.rate === null
          ? `${label}: ${r.rate} ${r.currency}/h — not settled: dataset 2026-09-12 says "${target.dataset?.scope ?? "no row"}".`
          : `${label}: ${r.rate} ${r.currency}/h; the dataset's ${target.rate} ${target.currency}/h governs.`);
      } else if (r.rate === null && target.rate === null && target.dataset?.published === null) {
        target.tier = tierOf(r);   // the dataset has not ruled on this place's structure; his flags say why nothing settles
      }
      ALIAS.set(regionId(r), target);
      continue;
    }
    // a place the dataset does not name — Austin, Beijing, Tokyo, Geneva, a Canadian province — stands on its own
    const key = `${r.cc}|${r.name}`;
    const found = byKey.get(key);
    if (found) {
      for (const l of [r.lang]) if (!found.langs.includes(l)) found.langs.push(l);
      if (!r.approved) found.fromOperator = true;
      // AN APPROVED FILL REPLACES THE OPERATOR'S NULL (Rule B): his row stays verbatim; the PLACE settles.
      if (r.approved && found.rate === null && r.rate !== null) {
        found.rate = r.rate; found.currency = r.currency; found.tier = tierOf(r); found.note = r.note; found.source = "approved-2026-09-11";
        found.history.push(`approved 2026-09-11 fills the operator's NULL: ${r.rate} ${r.currency}/h.`);
      }
      ALIAS.set(regionId(r), found);
      continue;
    }
    const j: Jurisdiction = {
      id: regionId(r), cc: r.cc, name: r.name, country, locality, currency: r.currency, rate: r.rate, tier: tierOf(r),
      note: r.note, langs: [r.lang], source: src, usdMirror: COUNTRY_RATES[country] ?? null, fromOperator: !r.approved, history: [],
    };
    byKey.set(key, j);
  }

  // 3 · hi_rates.py — "the live settlement table" (fund.token). Every US state is now a dataset place with the hi_rates
  // figure beside it as usdMirror; a country it holds that no source above names would be added here with its source.
  for (const [country, rate] of Object.entries(COUNTRY_RATES)) {
    if (Array.from(byKey.values()).some((j) => j.country === country)) continue;
    const cc = country === "Cambodia" ? "KH" : country.slice(0, 2).toUpperCase();
    byKey.set(`${cc}|${country}`, {
      id: `hi_rates:${cc}`, cc, name: country, country, locality: null, currency: "USD", rate, tier: "published",
      note: "Country rate — hi_rates.py; named by no other source (flagged)", langs: ["English"],
      source: "hi_rates.py", usdMirror: rate, fromOperator: false, history: [],
    });
  }
  return Array.from(byKey.values());
})();

/** The pre-existing region detector's result → the jurisdiction it names here, or undefined when it names none. */
export function jurisdictionFromResolved(r: ResolvedRegion | null | undefined): Jurisdiction | undefined {
  if (!r) return undefined;
  if (r.state) return JURISDICTIONS.find((j) => j.cc === "US" && j.rate !== null && (j.locality === r.state || j.locality?.startsWith(`${r.state} · `)));
  return JURISDICTIONS.find((j) => j.country === r.country && j.locality === null) ?? JURISDICTIONS.find((j) => j.country === r.country);
}

const JURIS_INDEX: ReadonlyMap<string, Jurisdiction> = (() => {
  const m = new Map<string, Jurisdiction>(JURISDICTIONS.map((j) => [j.id, j]));
  ALIAS.forEach((j, id) => { if (!m.has(id)) m.set(id, j); });   // an election recorded under a history id still resolves
  return m;
})();
export const findJurisdiction = (id: string): Jurisdiction | undefined => JURIS_INDEX.get(id);

/**
 * The four settlement tiers, grouped ONCE at module load. This was four `.filter(r => tierOf(r) === tier)` passes
 * rebuilt on every render in two places — 456 tierOf calls per render per picker, about to be tripled by per-member
 * election. Now it is a lookup.
 */
export const BY_TIER: Readonly<Record<SettleTier, Jurisdiction[]>> = (() => {
  const g: Record<SettleTier, Jurisdiction[]> = { published: [], pending: [], no_single_rate: [], no_official_rate: [] };
  for (const j of JURISDICTIONS) g[j.tier].push(j);
  return g;
})();

/** The tier headings, in the paper's own order. */
export const TIER_ORDER: readonly SettleTier[] = ["published", "pending", "no_single_rate", "no_official_rate"];
export const TIER_LABEL: Record<SettleTier, string> = {
  published: "Published rate",
  pending: "Rate exists, not yet loaded",
  no_single_rate: "No single national rate",
  no_official_rate: "No official rate",
};

/**
 * ELECTION OF LOCALITY, step two. The jurisdictions within one country, when a source publishes more than one — the
 * country itself first, then its localities in alphabetical order. Derived, so a locality row added later just works.
 */
const BY_COUNTRY: ReadonlyMap<string, Jurisdiction[]> = (() => {
  const m = new Map<string, Jurisdiction[]>();
  for (const j of JURISDICTIONS) (m.get(j.cc) ?? m.set(j.cc, []).get(j.cc)!).push(j);
  m.forEach((js) => js.sort((a, b) => (a.locality === null ? -1 : b.locality === null ? 1 : a.locality.localeCompare(b.locality))));
  return m;
})();
export const localitiesOf = (cc: string): Jurisdiction[] => {
  const all = BY_COUNTRY.get(cc) ?? [];
  return all.length > 1 ? all : [];
};

/** One entry per country for the first step of the election — the country itself, or its first rated place. */
export const COUNTRIES: Jurisdiction[] = Array.from(BY_COUNTRY.values())
  .map((js) => js.find((j) => j.locality === null) ?? js.find((j) => j.rate !== null) ?? js[0])
  .sort((a, b) => a.country.localeCompare(b.country));

/** The jurisdiction a country resolves to before any locality is chosen. */
const COUNTRY_DEFAULT: ReadonlyMap<string, Jurisdiction> = new Map(COUNTRIES.map((j) => [j.cc, j]));
export const defaultForCountry = (cc: string): Jurisdiction | undefined => COUNTRY_DEFAULT.get(cc);

/** Countries grouped by settlement tier, for the first step of the election. Precomputed, like BY_TIER. */
export const COUNTRIES_BY_TIER: Readonly<Record<SettleTier, Jurisdiction[]>> = (() => {
  const g: Record<SettleTier, Jurisdiction[]> = { published: [], pending: [], no_single_rate: [], no_official_rate: [] };
  for (const j of COUNTRIES) g[j.tier].push(j);
  return g;
})();

/**
 * D9 IN FULL (unit.regional, r272): "At settlement the payout takes the greater of two values from the same jurisdiction's
 * table: the vintage-locked rate at earning, or the current rate at settlement — a floor, never a ceiling, so time can only
 * preserve or improve real buying power … A contributor who relocates keeps the earning jurisdiction's vintage by
 * default; converting to the new schedule at settlement is an explicit election, closing jurisdiction-shopping."
 *
 * Grok, open.external #15: the figure moves only because a statutory wage moved. No conversion between currencies —
 * a relocation election settles on the NEW schedule at its current rate; it is never a max across two currencies.
 */
export interface D9Settlement { amount: number | null; rate: number | null; which: "vintage" | "current" | "equal" | "relocated" | "none"; currency: string | null }
export function settleD9(yug: number, vintage: { rate: number | null; currency: string | null } | null, current: Jurisdiction | undefined): D9Settlement {
  if (!(yug > 0)) return { amount: null, rate: null, which: "none", currency: null };
  const cur = current && current.rate !== null ? current.rate : null;
  const vin = vintage && vintage.rate !== null ? vintage.rate : null;
  if (vin !== null && vintage?.currency && current && current.currency !== vintage.currency) {
    // relocation: an explicit election onto another schedule — its current rate, never a cross-currency max
    return cur === null ? { amount: null, rate: null, which: "none", currency: current.currency }
                        : { amount: yug * cur, rate: cur, which: "relocated", currency: current.currency };
  }
  if (vin === null && cur === null) return { amount: null, rate: null, which: "none", currency: current?.currency ?? vintage?.currency ?? null };
  const rate = Math.max(vin ?? -Infinity, cur ?? -Infinity);
  const which = vin === null ? "current" : cur === null ? "vintage" : vin === cur ? "equal" : vin > cur ? "vintage" : "current";
  return { amount: yug * rate, rate, which, currency: current?.currency ?? vintage?.currency ?? null };
}

/**
 * The two decisions only the operator can take, exactly as the register records them (open.decisions, open since r57,
 * both "Blocks operation"). Shown as PROPOSALS on the rows they govern; nothing settles under them until ruled.
 */
export const OPEN_DECISION: Partial<Record<SettleTier, string>> = {
  no_single_rate: "D1, open since r57 — recommended default: the lowest generally-applicable adult rate in the contributor's own region, published with its source. Unsettled until the operator rules; blocks operation.",
  no_official_rate: "D2, open since r57 — the Global Agreed Standard: pegged to a published international reference, peg Stable, value Adaptive, reviewed annually. Unsettled until the operator rules; blocks operation.",
  pending: "Recoverable by data entry: a national rate exists and is not yet loaded here.",
};

/**
 * Settlement — `$ = 웃 × the region's hourly minimum wage`, in that region's own currency.
 * Returns null when the region publishes no rate: no contributor settles at zero, and no figure is guessed.
 */
export function settleInRegion(yug: number, r: { rate: number | null } | undefined): number | null {
  if (!r || r.rate === null || !(yug > 0)) return null;
  return yug * r.rate;
}

/**
 * Format an amount in its own currency. Falls back to "<code> <amount>" where a runtime has no data for the code —
 * printing the code is honest; substituting a symbol from another currency would not be.
 */
export function formatLocal(amount: number, currency: string, locale = "en"): string {
  try {
    return new Intl.NumberFormat(locale, { style: "currency", currency, maximumFractionDigits: 2 }).format(amount);
  } catch {
    return `${currency} ${amount.toLocaleString(locale, { maximumFractionDigits: 2 })}`;
  }
}

/**
 * THE USA EQUIVALENT — beside the local figure, never instead of it, and only by a route a person can trace:
 *   same-currency — the place settles in USD already (the United States, its territories, Ecuador, El Salvador …);
 *   fx            — a dated, sourced row in FX_TO_USD for this currency (docs/asks/2026-09-12_fx_to_usd.psv);
 *   hi_rates      — hi_rates.py holds a USD floor for this country: 웃 × that figure, the paper's own live settlement
 *                   table, which is a second floor in USD and NOT a conversion of the local amount.
 * With no route the function returns null and the screen says what is missing. No exchange rate is ever assumed.
 */
export interface UsdEquivalent { usd: number; via: "same-currency" | "fx" | "hi_rates"; asOf: string; source: string }
const FX_INDEX: ReadonlyMap<string, FxRow> = new Map(FX_TO_USD.map((f) => [f.currency, f]));
export function usdEquivalent(amount: number | null, currency: string | null, yug: number, place?: Pick<Jurisdiction, "usdMirror"> | null): UsdEquivalent | null {
  if (amount !== null && currency === "USD") return { usd: amount, via: "same-currency", asOf: "", source: "settles in USD" };
  const fx = currency ? FX_INDEX.get(currency) : undefined;
  if (amount !== null && fx && fx.perUsd > 0) return { usd: amount / fx.perUsd, via: "fx", asOf: fx.asOf, source: fx.source };
  if (place?.usdMirror != null && yug > 0) return { usd: yug * place.usdMirror, via: "hi_rates", asOf: "", source: "hi_rates.py USD floor × 웃 — a second floor, not a conversion" };
  return null;
}
export const USD_MISSING = "USD equivalent: awaiting a dated exchange-rate source for this currency";
export const formatUsd = (usd: number): string => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 2 }).format(usd);


/** The pod's default region — the paper's own worked example throughout is the Texas vintage (unit.ceiling). */
export const DEFAULT_REGION_ID = "English:US";
